    @_track_capability("site_stack_connections_summary")
    def read_site_stack_connections_summary(self, site_ref: str) -> dict[str, object]:
        """Summarize fresh stack membership and bounded LLDP coverage for one site."""
        site_id = self._resolve_site_ref(site_ref)
        try:
            from .site_stack_connections_summary import summarize_site_stack_connections
        except ImportError:  # direct execution in the image
            from site_stack_connections_summary import summarize_site_stack_connections

        inventory = self.list_devices(site_ref)
        if not isinstance(inventory.get("items"), list):
            raise OpenApiError("openapi_response_invalid")
        token = self._access_token()
        stack_path = self._SITE_STACK_LIST_PATH.format(
            controller_id=self.config.controller_id, site_id=site_id)
        source_errors: dict[str, str] = {}
        try:
            stack_rows, stack_omitted = self._read_bounded_grid_rows(
                stack_path, token, 32)
        except OpenApiError as exc:
            stack_rows, stack_omitted = [], 0
            source_errors["stack_list"] = exc.code

        neighbors_by_ref: dict[str, object] = {}
        neighbor_omitted_by_ref: dict[str, int] = {}
        seen_stack_ids: set[str] = set()
        for row in stack_rows:
            if not isinstance(row, Mapping):
                continue
            stack_id = row.get("id")
            if (type(stack_id) is not str or
                    not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", stack_id) or
                    stack_id in seen_stack_ids):
                continue
            seen_stack_ids.add(stack_id)
            stack_ref = self._opaque_ref("stack", site_id + ":" + stack_id)
            path = self._SITE_STACK_LLDP_PATH.format(
                controller_id=self.config.controller_id, site_id=site_id,
                stack_id=stack_id)
            try:
                neighbor_rows, omitted = self._read_bounded_grid_rows(
                    path, token, 64)
                neighbors_by_ref[stack_ref] = neighbor_rows
                if omitted:
                    neighbor_omitted_by_ref[stack_ref] = omitted
            except OpenApiError as exc:
                source_errors[stack_ref] = exc.code

        try:
            projected = summarize_site_stack_connections(
                stack_rows, self._switch_macs_by_site_ref.get(site_ref, {}),
                lambda stack_id: self._opaque_ref("stack", site_id + ":" + stack_id),
                neighbors_by_ref, stack_list_omitted=stack_omitted,
                neighbor_omitted_by_stack_ref=neighbor_omitted_by_ref,
                source_errors=source_errors)
        except ValueError:
            raise OpenApiError("openapi_response_invalid") from None
        return {"site_ref": site_ref, **projected}

    @_track_capability("site_stack_network_summary")
    def read_site_stack_network_summary(self, site_ref: str,
                                        stack_ref: str) -> dict[str, object]:
        """Summarize the documented network grid for one freshly inventoried stack."""
        site_id = self._resolve_site_ref(site_ref)
        if not isinstance(stack_ref, str) or not re.fullmatch(r"[0-9a-f]{24}", stack_ref):
            raise OpenApiError("stack_ref_invalid")
        stack_rows, stack_omitted = self._read_bounded_grid_rows(
            self._SITE_STACK_LIST_PATH.format(
                controller_id=self.config.controller_id, site_id=site_id),
            self._access_token(), 32)
        if stack_omitted:
            # The selected stack must be resolved from a complete, fresh bounded list.
            raise OpenApiError("stack_inventory_incomplete")
        matches: list[str] = []
        for row in stack_rows:
            if not isinstance(row, Mapping):
                continue
            stack_id = row.get("id")
            if (type(stack_id) is str and
                    re.fullmatch(r"[A-Za-z0-9_-]{1,128}", stack_id) and
                    self._opaque_ref("stack", site_id + ":" + stack_id) == stack_ref):
                matches.append(stack_id)
        if len(matches) != 1:
            raise OpenApiError("stack_ref_unknown" if not matches else "stack_ref_ambiguous")

        try:
            from .site_stack_network_summary import summarize_stack_networks
        except ImportError:  # direct execution in the image
            from site_stack_network_summary import summarize_stack_networks

        token = self._access_token()
        base_path = self._SITE_STACK_NETWORKS_PATH.format(
            controller_id=self.config.controller_id, site_id=site_id,
            stack_id=matches[0])
        page_size = min(self.config.page_size, 1000)
        rows: list[object] = []
        support_ipv6_values: list[object] = []
        total_rows: int | None = None
        for page in range(1, min(self.config.max_pages, 10) + 1):
            request_size = min(page_size, 1000 - len(rows))
            if request_size <= 0:
                break
            path = base_path + "?" + urlencode({"page": page, "pageSize": request_size})
            payload = self._request_json("GET", path, token=token)
            result = payload.get("result")
            data = result.get("data") if isinstance(result, dict) else None
            total = result.get("totalRows") if isinstance(result, dict) else None
            current_page = result.get("currentPage") if isinstance(result, dict) else None
            current_size = result.get("currentSize") if isinstance(result, dict) else None
            if (not isinstance(data, list) or len(data) > request_size or
                    type(total) is not int or total < 0 or
                    type(current_page) is not int or current_page != page or
                    type(current_size) is not int or current_size not in (len(data), request_size)):
                raise OpenApiError("openapi_response_invalid")
            if total_rows is None:
                total_rows = total
            elif total != total_rows:
                raise OpenApiError("openapi_response_invalid")
            support_ipv6_values.append(result.get("supportIpv6"))
            rows.extend(data)
            if len(rows) > 1000 or len(rows) > total:
                raise OpenApiError("openapi_response_invalid")
            if not data and len(rows) < total:
                raise OpenApiError("openapi_response_invalid")
            if len(rows) >= total:
                break
        if total_rows is None:
            raise OpenApiError("openapi_response_invalid")
        try:
            projected = summarize_stack_networks(
                stack_ref, rows, support_ipv6_values,
                omitted_network_count=max(0, total_rows - len(rows)))
        except ValueError:
            raise OpenApiError("openapi_response_invalid") from None
        return {"site_ref": site_ref, **projected}

    def _resolve_site_stack(self, site_ref: str, stack_ref: str,
                            token: str) -> tuple[str, str]:
        """Resolve a stack ref against a complete, fresh inventory for this site."""
        site_id = self._resolve_site_ref(site_ref)
        if type(stack_ref) is not str or not re.fullmatch(r"[0-9a-f]{24}", stack_ref):
            raise OpenApiError("stack_ref_invalid")
        rows, omitted = self._read_bounded_grid_rows(
            self._SITE_STACK_LIST_PATH.format(
                controller_id=self.config.controller_id, site_id=site_id),
            token, 32, require_success_code=True)
        if omitted:
            raise OpenApiError("stack_inventory_incomplete")
        seen: set[str] = set()
        matches: list[str] = []
        for row in rows:
            stack_id = row.get("id") if isinstance(row, Mapping) else None
            if (type(stack_id) is not str or
                    not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", stack_id) or
                    stack_id in seen):
                raise OpenApiError("stack_inventory_ambiguous")
            seen.add(stack_id)
            candidate = self._opaque_ref("stack", site_id + ":" + stack_id)
            if hmac.compare_digest(candidate, stack_ref):
                matches.append(stack_id)
        if len(matches) != 1:
            raise OpenApiError("stack_ref_unknown")
        return site_id, matches[0]

    def _read_stack_summary_grid(self, base_path: str,
                                 token: str) -> tuple[list[object], int, int]:
        """Read at most 1,000 stack-grid rows and retain the source total."""
        page_size = min(max(1, self.config.page_size), 1_000)
        page_limit = min(max(1, self.config.max_pages), 10)
        rows: list[object] = []
        total_rows: int | None = None
        for page in range(1, page_limit + 1):
            remaining_rows = (total_rows - len(rows)
                              if total_rows is not None else page_size)
            if min(1_000 - len(rows), remaining_rows) <= 0:
                break
            # Keep pageSize fixed: shrinking the last request changes the page
            # offset on controllers that use (page - 1) * pageSize.
            query = urlencode({"page": page, "pageSize": page_size})
            payload = self._request_json("GET", base_path + "?" + query, token=token)
            if type(payload.get("errorCode")) is not int or payload["errorCode"] != 0:
                raise OpenApiError("openapi_response_invalid")
            result = payload.get("result")
            data = result.get("data") if isinstance(result, Mapping) else None
            reported_total = result.get("totalRows") if isinstance(result, Mapping) else None
            current_page = result.get("currentPage") if isinstance(result, Mapping) else None
            current_size = result.get("currentSize") if isinstance(result, Mapping) else None
            empty_zero_page = (page == 1 and reported_total == 0 and current_page == 0 and
                               current_size == 0 and data == [])
            if (not isinstance(data, list) or len(data) > page_size or
                    type(reported_total) is not int or not 0 <= reported_total < (1 << 63) or
                    ((type(current_page) is not int or current_page != page) and
                     not empty_zero_page) or
                    type(current_size) is not int or
                    current_size not in (len(data), page_size) and not empty_zero_page):
                raise OpenApiError("openapi_response_invalid")
            if total_rows is None:
                total_rows = reported_total
            elif reported_total != total_rows:
                raise OpenApiError("openapi_response_invalid")
            if len(rows) + len(data) > reported_total:
                raise OpenApiError("openapi_response_invalid")
            rows.extend(data[:min(1_000 - len(rows), reported_total - len(rows))])
            if len(rows) > reported_total or len(rows) > 1_000:
                raise OpenApiError("openapi_response_invalid")
            if not data and len(rows) < reported_total:
                raise OpenApiError("openapi_response_invalid")
            if len(rows) >= reported_total:
                break
        if total_rows is None:
            raise OpenApiError("openapi_response_invalid")
        return rows, total_rows, max(0, total_rows - len(rows))

